-- Structure des tables de production (bakery-stock-management), sans aucune donnée.
-- Extraite le 2026-10-19 via pg_attribute / pg_constraint.

CREATE SEQUENCE audit_prix_changes_id_seq; CREATE SEQUENCE audit_prix_simple_id_seq; CREATE SEQUENCE caisses_actives_id_seq;
CREATE SEQUENCE consommations_atelier_id_seq; CREATE SEQUENCE demandes_id_seq; CREATE SEQUENCE demandes_groupees_id_seq;
CREATE SEQUENCE depenses_comptables_id_seq; CREATE SEQUENCE entrees_boutique_id_seq; CREATE SEQUENCE incidents_caisse_id_seq;
CREATE SEQUENCE lignes_vente_id_seq; CREATE SEQUENCE lignes_vente_cuisine_id_seq; CREATE SEQUENCE mouvements_stock_id_seq;
CREATE SEQUENCE mouvements_stock_cuisine_id_seq; CREATE SEQUENCE prix_vente_produits_id_seq; CREATE SEQUENCE productions_id_seq;
CREATE SEQUENCE produits_id_seq; CREATE SEQUENCE produits_cuisine_id_seq; CREATE SEQUENCE recettes_id_seq;
CREATE SEQUENCE referentiel_produits_id_seq; CREATE SEQUENCE releves_caisse_id_seq; CREATE SEQUENCE sorties_boutique_id_seq;
CREATE SEQUENCE stock_atelier_id_seq; CREATE SEQUENCE stock_boutique_id_seq; CREATE SEQUENCE stock_cuisine_id_seq;
CREATE SEQUENCE unites_id_seq; CREATE SEQUENCE utilisations_boutique_id_seq; CREATE SEQUENCE ventes_id_seq; CREATE SEQUENCE ventes_cuisine_id_seq;

CREATE TABLE public.annulations_ventes (id uuid DEFAULT gen_random_uuid() NOT NULL, vente_id integer NOT NULL, numero_ticket character varying(50) NOT NULL, montant_annule numeric(10,2) NOT NULL, motif text NOT NULL, annule_par uuid NOT NULL, annule_le timestamp with time zone DEFAULT now() NOT NULL, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.arrets_caisse (id uuid DEFAULT gen_random_uuid() NOT NULL, vendeur_id uuid, date_arret date NOT NULL, heure_debut timestamp without time zone, heure_fin timestamp without time zone, nombre_ventes integer, chiffre_affaires numeric(10,2), montant_attendu numeric(10,2), montant_declare numeric(10,2), ecart numeric(10,2), statut character varying(50) DEFAULT 'en_cours'::character varying, created_at timestamp without time zone DEFAULT now());
CREATE TABLE public.audit_prix_changes (id integer DEFAULT nextval('audit_prix_changes_id_seq'::regclass) NOT NULL, table_source character varying(50) NOT NULL, nom_produit text NOT NULL, ancien_prix numeric, nouveau_prix numeric, user_id uuid, user_name text, session_info jsonb, changed_at timestamp without time zone DEFAULT now(), changed_by_db_user text DEFAULT CURRENT_USER, ip_address inet, user_agent text, operation_type character varying(20), trigger_source character varying(100), additional_info jsonb, created_at timestamp without time zone DEFAULT now());
CREATE TABLE public.audit_prix_simple (id integer DEFAULT nextval('audit_prix_simple_id_seq'::regclass) NOT NULL, nom_produit text, ancien_prix numeric, nouveau_prix numeric, changed_at timestamp without time zone DEFAULT now(), user_db text DEFAULT CURRENT_USER, ip_address inet DEFAULT inet_client_addr());
CREATE TABLE public.caisses_actives (id bigint DEFAULT nextval('caisses_actives_id_seq'::regclass) NOT NULL, caissier_id uuid NOT NULL, date_ouverture timestamp with time zone DEFAULT now() NOT NULL, date_fermeture timestamp with time zone, fond_caisse_initial numeric(10,2) NOT NULL, montant_final numeric(10,2), caisse_precedente_id bigint, passation_de uuid, remplace_par uuid, poste_caisse character varying(50) DEFAULT 'principal'::character varying, statut character varying(20) DEFAULT 'ouverte'::character varying, details jsonb, releve_id bigint, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE public.consommations_atelier (id integer DEFAULT nextval('consommations_atelier_id_seq'::regclass) NOT NULL, production_id integer, produit_id integer, quantite_consommee numeric(10,2) NOT NULL, cout_unitaire numeric(10,2), created_at timestamp with time zone DEFAULT now(), date_consommation date DEFAULT CURRENT_DATE);
CREATE TABLE public.demandes (id integer DEFAULT nextval('demandes_id_seq'::regclass) NOT NULL, produit_id integer, quantite numeric(10,2) NOT NULL, destination character varying(100) DEFAULT 'Production'::character varying, statut character varying(50) DEFAULT 'en_attente'::character varying, demandeur_id uuid, valideur_id uuid, date_validation timestamp with time zone, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), demande_groupee_id bigint);
CREATE TABLE public.demandes_groupees (id bigint DEFAULT nextval('demandes_groupees_id_seq'::regclass) NOT NULL, destination character varying(100) DEFAULT 'Production'::character varying NOT NULL, commentaire text, demandeur_id uuid, valideur_id uuid, statut character varying(50) DEFAULT 'en_attente'::character varying NOT NULL, nombre_produits integer DEFAULT 0 NOT NULL, date_validation timestamp with time zone, details_validation jsonb, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE public.depenses_comptables (id integer DEFAULT nextval('depenses_comptables_id_seq'::regclass) NOT NULL, type_depense character varying NOT NULL, description text NOT NULL, montant numeric NOT NULL, reference_produit_id integer, date_depense date DEFAULT CURRENT_DATE NOT NULL, utilisateur_id uuid, details jsonb, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), pieces_jointes jsonb DEFAULT '[]'::jsonb, commentaire text, categorie character varying, numero_facture character varying, recurrent boolean DEFAULT false);
CREATE TABLE public.entrees_boutique (id integer DEFAULT nextval('entrees_boutique_id_seq'::regclass) NOT NULL, produit_id integer, quantite numeric NOT NULL, source character varying(50) DEFAULT 'Production'::character varying, source_id integer, type_entree character varying(50) DEFAULT 'Production'::character varying, ajoute_par uuid, created_at timestamp with time zone DEFAULT now(), prix_vente numeric(10,2));
CREATE TABLE public.incidents_caisse (id bigint DEFAULT nextval('incidents_caisse_id_seq'::regclass) NOT NULL, releve_id bigint, caissier_id uuid, type_incident character varying(50), montant numeric(10,2), description text NOT NULL, resolution text, resolu boolean DEFAULT false, resolu_par uuid, date_resolution timestamp with time zone, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.lignes_vente (id integer DEFAULT nextval('lignes_vente_id_seq'::regclass) NOT NULL, vente_id integer, produit_id integer, nom_produit character varying(255), quantite numeric NOT NULL, prix_unitaire numeric NOT NULL, total numeric NOT NULL, created_at timestamp without time zone DEFAULT now());
CREATE TABLE public.lignes_vente_cuisine (id integer DEFAULT nextval('lignes_vente_cuisine_id_seq'::regclass) NOT NULL, vente_cuisine_id integer NOT NULL, produit_cuisine_id integer NOT NULL, nom_produit character varying(255) NOT NULL, quantite numeric(10,2) NOT NULL, prix_unitaire numeric(10,2) NOT NULL, sous_total numeric(10,2) NOT NULL, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.modules (id uuid DEFAULT gen_random_uuid() NOT NULL, code character varying NOT NULL, nom character varying NOT NULL, description text, icone character varying, ordre integer DEFAULT 0, actif boolean DEFAULT true, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.mouvements_stock (id integer DEFAULT nextval('mouvements_stock_id_seq'::regclass) NOT NULL, produit_id integer, type_mouvement character varying(50) NOT NULL, quantite numeric(10,2) NOT NULL, quantite_avant numeric(10,2), quantite_apres numeric(10,2), utilisateur_id uuid, reference_id integer, commentaire text, created_at timestamp with time zone DEFAULT now(), reference_type character varying(50), raison text, destination character varying, source character varying, prix_unitaire numeric, motif text);
CREATE TABLE public.mouvements_stock_cuisine (id integer DEFAULT nextval('mouvements_stock_cuisine_id_seq'::regclass) NOT NULL, produit_cuisine_id integer NOT NULL, type_mouvement character varying(50) NOT NULL, quantite numeric(10,2) NOT NULL, quantite_avant numeric(10,2), quantite_apres numeric(10,2), utilisateur_id uuid, reference_id integer, commentaire text, raison text, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.notifications (id uuid DEFAULT gen_random_uuid() NOT NULL, destinataire_id uuid NOT NULL, emetteur_id uuid, type character varying NOT NULL, message text NOT NULL, details text, lien character varying, lu boolean DEFAULT false, date_lecture timestamp with time zone, priorite character varying DEFAULT 'normale'::character varying, expire_at timestamp with time zone, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.password_change_log (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid, changed_at timestamp with time zone DEFAULT now(), changed_by uuid, reason text DEFAULT 'User initiated'::text, ip_address inet, user_agent text);
CREATE TABLE public.permissions (id uuid DEFAULT gen_random_uuid() NOT NULL, module_id uuid NOT NULL, code character varying NOT NULL, nom character varying NOT NULL, description text, type character varying, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.prix_baseline_surveillance (source text, nom_produit text, prix_vente numeric, updated_at timestamp with time zone, baseline_created_at timestamp with time zone);
CREATE TABLE public.prix_baseline_surveillance_backup (source text, nom_produit text, prix_vente numeric, updated_at timestamp with time zone, baseline_created_at timestamp with time zone);
CREATE TABLE public.prix_vente_produits (id integer DEFAULT nextval('prix_vente_produits_id_seq'::regclass) NOT NULL, produit_id integer, prix numeric NOT NULL, marge_pourcentage numeric DEFAULT 0, actif boolean DEFAULT true, created_at timestamp without time zone DEFAULT now());
CREATE TABLE public.prix_vente_recettes (id uuid DEFAULT gen_random_uuid() NOT NULL, nom_produit text NOT NULL, prix_vente numeric NOT NULL, defini_par uuid, actif boolean DEFAULT true, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE public.productions (id integer DEFAULT nextval('productions_id_seq'::regclass) NOT NULL, produit character varying(200) NOT NULL, quantite numeric(10,2) NOT NULL, destination character varying(100) DEFAULT 'Boutique'::character varying, date_production date DEFAULT CURRENT_DATE NOT NULL, statut character varying(50) DEFAULT 'termine'::character varying, producteur_id uuid, cout_ingredients numeric(10,2), created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE public.produits (id integer DEFAULT nextval('produits_id_seq'::regclass) NOT NULL, nom character varying(200) NOT NULL, date_achat date DEFAULT CURRENT_DATE NOT NULL, prix_achat numeric(10,2) NOT NULL, quantite numeric(10,2) NOT NULL, quantite_restante numeric(10,2) NOT NULL, unite_id integer, created_by uuid, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE public.produits_cuisine (id integer DEFAULT nextval('produits_cuisine_id_seq'::regclass) NOT NULL, nom character varying(255) NOT NULL, description text, prix_vente numeric(10,2) NOT NULL, unite_id integer, categorie character varying(100), actif boolean DEFAULT true, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), created_by uuid);
CREATE TABLE public.profiles (id uuid NOT NULL, username character varying(50), nom character varying(100), telephone character varying(20), role character varying(50) DEFAULT 'employe_boutique'::character varying, actif boolean DEFAULT true, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), force_password_change boolean DEFAULT true, last_password_change timestamp with time zone, permissions_onglets jsonb DEFAULT '{}'::jsonb, custom_role_id uuid, is_super_admin boolean DEFAULT false);
CREATE TABLE public.recettes (id integer DEFAULT nextval('recettes_id_seq'::regclass) NOT NULL, nom_produit character varying(200) NOT NULL, produit_ingredient_id integer, quantite_necessaire numeric(10,2) NOT NULL, created_by uuid, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE public.referentiel_produits (id integer DEFAULT nextval('referentiel_produits_id_seq'::regclass) NOT NULL, reference character varying(50) NOT NULL, nom character varying(255) NOT NULL, type_conditionnement character varying(100) DEFAULT 'sac'::character varying NOT NULL, unite_mesure character varying(20) DEFAULT 'kg'::character varying NOT NULL, quantite_par_conditionnement numeric NOT NULL, prix_achat_total numeric NOT NULL, prix_unitaire numeric GENERATED ALWAYS AS (prix_achat_total / quantite_par_conditionnement) STORED, actif boolean DEFAULT true, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE public.releves_caisse (id bigint DEFAULT nextval('releves_caisse_id_seq'::regclass) NOT NULL, caisse_active_id bigint, caissier_id uuid NOT NULL, date_releve timestamp with time zone DEFAULT now() NOT NULL, fond_caisse_initial numeric(10,2) NOT NULL, total_ventes numeric(10,2) DEFAULT 0 NOT NULL, nombre_ventes integer DEFAULT 0, montant_theorique numeric(10,2) NOT NULL, montant_reel numeric(10,2) NOT NULL, ecart numeric(10,2) GENERATED ALWAYS AS (montant_reel - montant_theorique) STORED, details_ventes jsonb, duree_shift character varying(20), statut character varying(20) DEFAULT 'complete'::character varying, observations text, valide_par uuid, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.role_permissions (id uuid DEFAULT gen_random_uuid() NOT NULL, role_id uuid NOT NULL, permission_id uuid NOT NULL, accorded_by uuid, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.roles_custom (id uuid DEFAULT gen_random_uuid() NOT NULL, nom character varying NOT NULL, description text, is_system boolean DEFAULT false, is_super_admin boolean DEFAULT false, created_by uuid, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE public.sorties_boutique (id integer DEFAULT nextval('sorties_boutique_id_seq'::regclass) NOT NULL, vente_id integer, produit_id integer, quantite numeric NOT NULL, prix_unitaire numeric NOT NULL, total numeric NOT NULL, created_at timestamp without time zone DEFAULT now());
CREATE TABLE public.stock_atelier (id bigint DEFAULT nextval('stock_atelier_id_seq'::regclass) NOT NULL, produit_id bigint, quantite_disponible numeric DEFAULT 0 NOT NULL, quantite_reservee numeric DEFAULT 0 NOT NULL, transfere_par uuid, statut text DEFAULT 'effectue'::text, derniere_maj timestamp with time zone DEFAULT now(), created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE public.stock_boutique (id integer DEFAULT nextval('stock_boutique_id_seq'::regclass) NOT NULL, produit_id integer, quantite_disponible numeric DEFAULT 0, quantite_vendue numeric DEFAULT 0, prix_vente numeric, statut_stock character varying(20) DEFAULT 'normal'::character varying, transfere_par uuid, created_at timestamp without time zone DEFAULT now(), updated_at timestamp without time zone DEFAULT now(), nom_produit text, type_produit character varying(20) DEFAULT 'vendable'::character varying NOT NULL, quantite_utilisee numeric DEFAULT 0);
CREATE TABLE public.stock_cuisine (id integer DEFAULT nextval('stock_cuisine_id_seq'::regclass) NOT NULL, produit_cuisine_id integer NOT NULL, quantite_disponible numeric(10,2) DEFAULT 0 NOT NULL, quantite_vendue numeric(10,2) DEFAULT 0, prix_vente numeric(10,2), created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE public.unites (id integer DEFAULT nextval('unites_id_seq'::regclass) NOT NULL, value character varying(50) NOT NULL, label character varying(100) NOT NULL, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.user_permissions (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid NOT NULL, permission_id uuid NOT NULL, granted boolean DEFAULT true, accorded_by uuid, reason text, expires_at timestamp with time zone, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.utilisations_boutique (id integer DEFAULT nextval('utilisations_boutique_id_seq'::regclass) NOT NULL, stock_boutique_id integer NOT NULL, quantite_utilisee numeric NOT NULL, utilisateur_id uuid NOT NULL, raison text, date_utilisation timestamp with time zone DEFAULT now(), created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.ventes (id integer DEFAULT nextval('ventes_id_seq'::regclass) NOT NULL, numero_ticket character varying(50), total numeric NOT NULL, montant_donne numeric NOT NULL, monnaie_rendue numeric NOT NULL, vendeur_id uuid, statut character varying(20) DEFAULT 'validee'::character varying, created_at timestamp without time zone DEFAULT now());
CREATE TABLE public.ventes_cuisine (id integer DEFAULT nextval('ventes_cuisine_id_seq'::regclass) NOT NULL, numero_ticket character varying(50) NOT NULL, vendeur_id uuid NOT NULL, total numeric(10,2) NOT NULL, montant_donne numeric(10,2) NOT NULL, monnaie_rendue numeric(10,2) DEFAULT 0, statut character varying(50) DEFAULT 'validee'::character varying, note text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());

-- Clés primaires, unicité et contraintes CHECK (identiques à la production)
ALTER TABLE annulations_ventes ADD PRIMARY KEY (id);
ALTER TABLE arrets_caisse ADD PRIMARY KEY (id);
ALTER TABLE audit_prix_changes ADD PRIMARY KEY (id);
ALTER TABLE audit_prix_simple ADD PRIMARY KEY (id);
ALTER TABLE caisses_actives ADD PRIMARY KEY (id);
ALTER TABLE caisses_actives ADD CONSTRAINT caisses_actives_statut_check CHECK (statut IN ('ouverte','en_passation','fermee'));
ALTER TABLE consommations_atelier ADD PRIMARY KEY (id);
ALTER TABLE consommations_atelier ADD CONSTRAINT positive_quantite_consommee CHECK (quantite_consommee > 0);
ALTER TABLE demandes ADD PRIMARY KEY (id);
ALTER TABLE demandes ADD CONSTRAINT demandes_statut_check CHECK (statut IN ('en_attente','en_traitement','validee','refusee','annulee','erreur','partiellement_validee'));
ALTER TABLE demandes ADD CONSTRAINT valid_statut_demande CHECK (statut IN ('en_attente','validee','refusee','partiellement_validee'));
ALTER TABLE demandes ADD CONSTRAINT positive_quantite CHECK (quantite > 0);
ALTER TABLE demandes_groupees ADD PRIMARY KEY (id);
ALTER TABLE demandes_groupees ADD CONSTRAINT demandes_groupees_statut_check CHECK (statut IN ('en_attente','en_traitement','validee','refusee','annulee','partiellement_validee'));
ALTER TABLE depenses_comptables ADD PRIMARY KEY (id);
ALTER TABLE depenses_comptables ADD CONSTRAINT depenses_comptables_type_depense_check CHECK (type_depense IN ('achat_stock','reapprovisionnement_stock','frais_generaux','salaires','loyer','electricite','eau','transport','marketing','maintenance','fournitures','autre'));
ALTER TABLE depenses_comptables ADD CONSTRAINT depenses_comptables_montant_check CHECK (montant >= 0);
ALTER TABLE entrees_boutique ADD PRIMARY KEY (id);
ALTER TABLE incidents_caisse ADD PRIMARY KEY (id);
ALTER TABLE incidents_caisse ADD CONSTRAINT incidents_caisse_type_incident_check CHECK (type_incident IN ('ecart_important','fausse_monnaie','erreur_rendu','autre'));
ALTER TABLE lignes_vente ADD PRIMARY KEY (id);
ALTER TABLE lignes_vente_cuisine ADD PRIMARY KEY (id);
ALTER TABLE modules ADD PRIMARY KEY (id);
ALTER TABLE modules ADD CONSTRAINT modules_code_key UNIQUE (code);
ALTER TABLE mouvements_stock ADD PRIMARY KEY (id);
ALTER TABLE mouvements_stock ADD CONSTRAINT valid_type_mouvement CHECK (type_mouvement IN ('entree','sortie','transfert','ajustement','utilisation_production','restauration_annulation'));
ALTER TABLE mouvements_stock_cuisine ADD PRIMARY KEY (id);
ALTER TABLE mouvements_stock_cuisine ADD CONSTRAINT mouvements_stock_cuisine_type_mouvement_check CHECK (type_mouvement IN ('entree','sortie','ajustement','vente'));
ALTER TABLE notifications ADD PRIMARY KEY (id);
ALTER TABLE notifications ADD CONSTRAINT notifications_priorite_check CHECK (priorite IN ('basse','normale','haute','urgente'));
ALTER TABLE notifications ADD CONSTRAINT notifications_type_check CHECK (type IN ('demande_nouvelle','demande_validee','demande_refusee','demande_modifiee','stock_faible','stock_rupture','production_terminee','vente_importante','alerte_generale','message_admin'));
ALTER TABLE password_change_log ADD PRIMARY KEY (id);
ALTER TABLE permissions ADD PRIMARY KEY (id);
ALTER TABLE permissions ADD CONSTRAINT permissions_unique_code UNIQUE (module_id, code);
ALTER TABLE prix_vente_produits ADD PRIMARY KEY (id);
ALTER TABLE prix_vente_recettes ADD PRIMARY KEY (id);
ALTER TABLE prix_vente_recettes ADD CONSTRAINT prix_vente_recettes_nom_produit_key UNIQUE (nom_produit);
ALTER TABLE productions ADD PRIMARY KEY (id);
ALTER TABLE productions ADD CONSTRAINT valid_statut_production CHECK (statut IN ('en_cours','termine','annule'));
ALTER TABLE productions ADD CONSTRAINT positive_quantite_prod CHECK (quantite > 0);
ALTER TABLE produits ADD PRIMARY KEY (id);
ALTER TABLE produits ADD CONSTRAINT produits_nom_unique UNIQUE (nom, date_achat);
ALTER TABLE produits ADD CONSTRAINT positive_quantities CHECK (quantite > 0 AND quantite_restante >= 0 AND quantite_restante <= quantite);
ALTER TABLE produits_cuisine ADD PRIMARY KEY (id);
ALTER TABLE profiles ADD PRIMARY KEY (id);
ALTER TABLE profiles ADD CONSTRAINT profiles_username_key UNIQUE (username);
ALTER TABLE profiles ADD CONSTRAINT profiles_role_check CHECK (role IN ('admin','employe_boutique','employe_cuisine'));
ALTER TABLE profiles ADD CONSTRAINT valid_role CHECK (role IN ('admin','employe_production','employe_boutique'));
ALTER TABLE recettes ADD PRIMARY KEY (id);
ALTER TABLE recettes ADD CONSTRAINT recettes_nom_produit_produit_ingredient_id_key UNIQUE (nom_produit, produit_ingredient_id);
ALTER TABLE referentiel_produits ADD PRIMARY KEY (id);
ALTER TABLE referentiel_produits ADD CONSTRAINT referentiel_produits_reference_key UNIQUE (reference);
ALTER TABLE releves_caisse ADD PRIMARY KEY (id);
ALTER TABLE role_permissions ADD PRIMARY KEY (id);
ALTER TABLE roles_custom ADD PRIMARY KEY (id);
ALTER TABLE roles_custom ADD CONSTRAINT roles_custom_nom_key UNIQUE (nom);
ALTER TABLE sorties_boutique ADD PRIMARY KEY (id);
ALTER TABLE stock_atelier ADD PRIMARY KEY (id);
ALTER TABLE stock_atelier ADD CONSTRAINT stock_atelier_produit_id_key UNIQUE (produit_id);
ALTER TABLE stock_boutique ADD PRIMARY KEY (id);
ALTER TABLE stock_boutique ADD CONSTRAINT valid_type_produit CHECK (type_produit IN ('vendable','emballage','fourniture','materiel','consommable'));
ALTER TABLE stock_cuisine ADD PRIMARY KEY (id);
ALTER TABLE stock_cuisine ADD CONSTRAINT stock_cuisine_produit_cuisine_id_key UNIQUE (produit_cuisine_id);
ALTER TABLE unites ADD PRIMARY KEY (id);
ALTER TABLE unites ADD CONSTRAINT unites_value_key UNIQUE (value);
ALTER TABLE user_permissions ADD PRIMARY KEY (id);
ALTER TABLE utilisations_boutique ADD PRIMARY KEY (id);
ALTER TABLE ventes ADD PRIMARY KEY (id);
ALTER TABLE ventes ADD CONSTRAINT ventes_numero_ticket_key UNIQUE (numero_ticket);
ALTER TABLE ventes_cuisine ADD PRIMARY KEY (id);
ALTER TABLE ventes_cuisine ADD CONSTRAINT ventes_cuisine_numero_ticket_key UNIQUE (numero_ticket);

-- Clés étrangères principales (celles que les tests traversent)
ALTER TABLE profiles ADD CONSTRAINT profiles_id_fkey FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;
ALTER TABLE lignes_vente ADD FOREIGN KEY (vente_id) REFERENCES ventes(id) ON DELETE CASCADE;
ALTER TABLE lignes_vente ADD FOREIGN KEY (produit_id) REFERENCES produits(id) ON DELETE SET NULL;
ALTER TABLE sorties_boutique ADD FOREIGN KEY (vente_id) REFERENCES ventes(id) ON DELETE CASCADE;
ALTER TABLE ventes ADD FOREIGN KEY (vendeur_id) REFERENCES profiles(id) ON DELETE SET NULL;
ALTER TABLE stock_boutique ADD FOREIGN KEY (produit_id) REFERENCES produits(id) ON DELETE CASCADE;
ALTER TABLE stock_boutique ADD FOREIGN KEY (transfere_par) REFERENCES profiles(id) ON DELETE SET NULL;
ALTER TABLE stock_atelier ADD FOREIGN KEY (produit_id) REFERENCES produits(id) ON DELETE CASCADE;
ALTER TABLE produits ADD FOREIGN KEY (unite_id) REFERENCES unites(id);
ALTER TABLE produits ADD FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE SET NULL;
ALTER TABLE entrees_boutique ADD FOREIGN KEY (produit_id) REFERENCES produits(id) ON DELETE SET NULL;
ALTER TABLE entrees_boutique ADD FOREIGN KEY (ajoute_par) REFERENCES profiles(id);
ALTER TABLE notifications ADD FOREIGN KEY (destinataire_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE notifications ADD FOREIGN KEY (emetteur_id) REFERENCES profiles(id) ON DELETE SET NULL;
ALTER TABLE password_change_log ADD FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE demandes_groupees ADD FOREIGN KEY (demandeur_id) REFERENCES profiles(id) ON DELETE SET NULL;
ALTER TABLE demandes ADD FOREIGN KEY (demande_groupee_id) REFERENCES demandes_groupees(id) ON DELETE CASCADE;
ALTER TABLE utilisations_boutique ADD FOREIGN KEY (stock_boutique_id) REFERENCES stock_boutique(id) ON DELETE CASCADE;
ALTER TABLE annulations_ventes ADD FOREIGN KEY (vente_id) REFERENCES ventes(id) ON DELETE CASCADE;

-- RLS déjà actif en production sur ces 20 tables
ALTER TABLE annulations_ventes ENABLE ROW LEVEL SECURITY; ALTER TABLE consommations_atelier ENABLE ROW LEVEL SECURITY;
ALTER TABLE demandes_groupees ENABLE ROW LEVEL SECURITY; ALTER TABLE depenses_comptables ENABLE ROW LEVEL SECURITY;
ALTER TABLE lignes_vente_cuisine ENABLE ROW LEVEL SECURITY; ALTER TABLE modules ENABLE ROW LEVEL SECURITY;
ALTER TABLE mouvements_stock ENABLE ROW LEVEL SECURITY; ALTER TABLE mouvements_stock_cuisine ENABLE ROW LEVEL SECURITY;
ALTER TABLE notifications ENABLE ROW LEVEL SECURITY; ALTER TABLE password_change_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE permissions ENABLE ROW LEVEL SECURITY; ALTER TABLE productions ENABLE ROW LEVEL SECURITY;
ALTER TABLE produits_cuisine ENABLE ROW LEVEL SECURITY; ALTER TABLE recettes ENABLE ROW LEVEL SECURITY;
ALTER TABLE referentiel_produits ENABLE ROW LEVEL SECURITY; ALTER TABLE role_permissions ENABLE ROW LEVEL SECURITY;
ALTER TABLE roles_custom ENABLE ROW LEVEL SECURITY; ALTER TABLE stock_cuisine ENABLE ROW LEVEL SECURITY;
ALTER TABLE user_permissions ENABLE ROW LEVEL SECURITY; ALTER TABLE ventes_cuisine ENABLE ROW LEVEL SECURITY;
